// Drizzle schema: the source of truth for the tables.
// The Better Auth tables (user, session, account, verification) live in auth-schema.ts,
// generated by `pnpm dlx @better-auth/cli generate`. The admin plugin adds user.role.
import { relations } from "drizzle-orm";
import {
  date,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import { coverColors, coverPatterns } from "../lib/domain/book-cover";
import { user } from "./auth-schema";

export * from "./auth-schema";

export const bookStatus = pgEnum("book_status", [
  "draft",
  "in_review",
  "published",
  "rejected",
  "needs_human",
]);

export const coverColor = pgEnum("cover_color", coverColors);

export const coverPattern = pgEnum("cover_pattern", coverPatterns);

export const pageLayout = pgEnum("page_layout", ["text", "photo", "photo+text"]);

export const reviewSource = pgEnum("review_source", ["rules", "ai", "admin"]);

export const reviewDecision = pgEnum("review_decision", ["approve", "reject", "needs_human"]);

const timestamps = {
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
};

export const pets = pgTable(
  "pets",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    species: text("species").notNull(),
    bornOn: date("born_on"),
    adoptedOn: date("adopted_on"),
    passedOn: date("passed_on"),
    // Only the city and coordinates rounded by fuzzLocation(). Never a precise address.
    // Optional while the book is a draft; canPublish() requires them.
    city: text("city"),
    lat: doublePrecision("lat"),
    lng: doublePrecision("lng"),
    ...timestamps,
  },
  (table) => [index("pets_owner_id_idx").on(table.ownerId)],
);

export const books = pgTable(
  "books",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // One book per pet for now.
    petId: uuid("pet_id")
      .notNull()
      .unique()
      .references(() => pets.id, { onDelete: "cascade" }),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    slug: text("slug").notNull().unique(),
    coverUrl: text("cover_url"),
    coverColor: coverColor("cover_color").default("sage").notNull(),
    coverPattern: coverPattern("cover_pattern").default("paws").notNull(),
    status: bookStatus("status").default("draft").notNull(),
    publishedAt: timestamp("published_at"),
    ...timestamps,
  },
  (table) => [
    index("books_owner_id_idx").on(table.ownerId),
    index("books_status_idx").on(table.status),
  ],
);

export const pages = pgTable(
  "pages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    bookId: uuid("book_id")
      .notNull()
      .references(() => books.id, { onDelete: "cascade" }),
    // 0..n-1 within a book, kept contiguous by movePage().
    position: integer("position").notNull(),
    layout: pageLayout("layout").notNull(),
    text: text("text"),
    imageUrl: text("image_url"),
    caption: text("caption"),
    ...timestamps,
  },
  (table) => [index("pages_book_id_idx").on(table.bookId)],
);

export const reviews = pgTable(
  "reviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    bookId: uuid("book_id")
      .notNull()
      .references(() => books.id, { onDelete: "cascade" }),
    source: reviewSource("source").notNull(),
    decision: reviewDecision("decision").notNull(),
    reasons: jsonb("reasons").$type<string[]>().default([]).notNull(),
    // Set only when source = 'admin'.
    reviewerId: text("reviewer_id").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [index("reviews_book_id_idx").on(table.bookId)],
);

export const petsRelations = relations(pets, ({ one }) => ({
  owner: one(user, { fields: [pets.ownerId], references: [user.id] }),
  book: one(books),
}));

export const booksRelations = relations(books, ({ one, many }) => ({
  pet: one(pets, { fields: [books.petId], references: [pets.id] }),
  owner: one(user, { fields: [books.ownerId], references: [user.id] }),
  pages: many(pages),
  reviews: many(reviews),
}));

export const pagesRelations = relations(pages, ({ one }) => ({
  book: one(books, { fields: [pages.bookId], references: [books.id] }),
}));

export const reviewsRelations = relations(reviews, ({ one }) => ({
  book: one(books, { fields: [reviews.bookId], references: [books.id] }),
  reviewer: one(user, { fields: [reviews.reviewerId], references: [user.id] }),
}));
